1	import * as THREE from "three";
2	import { VoxelWorld, type BlockId } from "@/lib/world";
3	import type { BossTracking } from "@/lib/game/bossTracking";
4	import type { GameMode } from "@/lib/game/gameModes";
5	import type { Difficulty } from "@/lib/game/difficulties";
6	import type { EffectId, EnchantmentId, EquippedArmor, InventorySlot, MobKind, SaveData } from "@/lib/game/types";
7	import type { BlockChangeTracker } from "./blockChanges";
8	import type { Command } from "./commands";
9	
10	/** Session-only camera presentation mode; never persisted. Gameplay stays eye-relative in all modes. */
11	export type CameraMode = "first" | "third-rear" | "third-front";
12	
13	const CAMERA_MODE_CYCLE: readonly CameraMode[] = ["first", "third-rear", "third-front"];
14	
15	export function nextCameraMode(mode: CameraMode): CameraMode {
16	  return CAMERA_MODE_CYCLE[(CAMERA_MODE_CYCLE.indexOf(mode) + 1) % CAMERA_MODE_CYCLE.length];
17	}
18	
19	export type PlayerState = {
20	  position: THREE.Vector3;
21	  velocity: THREE.Vector3;
22	  /** Look direction; the renderer derives the camera from these. Order YXZ. */
23	  yaw: number;
24	  pitch: number;
25	  onGround: boolean;
26	};
27	
28	/** Simulation-side mob — no Three.js objects; visuals live in the renderer. */
29	export type MobState = {
30	  id: number;
31	  kind: MobKind;
32	  hostile: boolean;
33	  hp: number;
34	  /** Body center (ground + halfHeight), like the old group.position without bob. */
35	  position: THREE.Vector3;
36	  direction: THREE.Vector3;
37	  yaw: number;
38	  turnTimer: number;
39	  speed: number;
40	  /** Speed after aggro/flee multipliers this tick; renderer uses it for gait. */
41	  moveSpeed: number;
42	  detectRange: number;
43	  attackDamage: number;
44	  attackCooldown: number;
45	  attackTimer: number;
46	  halfHeight: number;
47	  bobSeed: number;
48	  /** Seconds left "in love" after being fed; pairs with another to breed. */
49	  fedTimer: number;
50	  /** Seconds left as a baby; > 0 means a scaled-down, no-drop juvenile. */
51	  ageTimer: number;
52	  /** Boss-only: seconds until the next minion summon (session-only, never saved). */
53	  summonTimer?: number;
54	  /** Creeper-only: seconds left on a lit fuse (>0 means primed); detonates at 0. Session-only. */
55	  fuseTimer?: number;
56	};
57	
58	/**
59	 * Simulation-side projectile (arrow) — transient, never serialized, like mobs.
60	 * Shared by the player's bow, ranged skeletons, and the boss; `fromPlayer` is
61	 * the hit filter (player arrows hit mobs, mob arrows hit the player).
62	 */
63	export type ProjectileState = {
64	  id: number;
65	  position: THREE.Vector3;
66	  /** m/s; gravity-integrated each step. yaw/pitch are derived from it for the renderer. */
67	  velocity: THREE.Vector3;
68	  yaw: number;
69	  pitch: number;
70	  damage: number;
71	  knockback: number;
72	  fromPlayer: boolean;
73	  /** Seconds remaining before the arrow despawns mid-air. */
74	  ttl: number;
75	};
76	
77	export type MiningState = {
78	  /** "x,y,z" of the block being mined, or "" when idle. */
79	  targetKey: string;
80	  progress: number;
81	};
82	
83	export type ThrownSpearState = {
84	  id: number;
85	  itemId: string;
86	  position: THREE.Vector3;
87	  velocity: THREE.Vector3;
88	  damage: number;
89	  age: number;
90	  /** Seconds embedded in terrain, or null while still flying. */
91	  stuckTimer: number | null;
92	};
93	
94	/**
95	 * The one active fishing cast — session-only, never serialized (like projectiles).
96	 * `timer` counts down to the next state change: while `!biting` it's the wait for a
97	 * bite; once `biting` it's the reel window before the catch gets away.
98	 */
99	export type FishingState = {
100	  position: THREE.Vector3;
101	  timer: number;
102	  biting: boolean;
103	};
104	
105	/** Throttled (~4 Hz) readout for the F3 overlay; null while the overlay is closed. */
106	export type DebugInfo = {
107	  x: number;
108	  y: number;
109	  z: number;
110	  daylight: number;
111	};
112	
113	export type GameTimers = {
114	  voidTimer: number;
115	  regenTimer: number;
116	  waterExposureTimer: number;
117	  waterDamageTimer: number;
118	  /** Seconds of lava burn left; refreshed to LAVA_BURN_SECONDS on contact. */
119	  lavaBurnTimer: number;
120	  lavaDamageTimer: number;
121	  /** Accumulates drowning damage once oxygen is exhausted. */
122	  drownTimer: number;
123	  /** Accumulates starvation damage while hunger sits at 0 (difficulty-gated). */
124	  starvationTimer: number;
125	  sprintDistanceBudget: number;
126	  walkDistanceBudget: number;
127	  jumpBudget: number;
128	  /** Regeneration-effect heal accumulator — independent of the hunger-gated regenTimer. */
129	  effectRegenTimer: number;
130	  /** Poison-effect damage accumulator. */
131	  effectPoisonTimer: number;
132	  stuckTimer: number;
133	  hostileSpawnTimer: number;
134	  spawnerTimer: number;
135	  daylightHudTimer: number;
136	  debugHudTimer: number;
137	  randomTickTimer: number;
138	  breedTimer: number;
139	  spearThrowCooldown: number;
140	  /** Seconds until the bow can fire again (instant click-to-fire rate limit). */
141	  bowCooldownTimer: number;
142	};
143	
144	export type WeatherKind = "clear" | "rain" | "snow";
145	export type WeatherState = { kind: WeatherKind; intensity: number };
146	
147	export type GameState = {
148	  world: VoxelWorld;
149	  blockChanges: BlockChangeTracker;
150	  player: PlayerState;
151	  inventory: InventorySlot[];
152	  equippedArmor: EquippedArmor;
153	  selectedSlot: number;
154	  /** Current game mode. Persisted (save v8); switchable in-game via setGameMode. */
155	  gameMode: GameMode;
156	  /** Current difficulty. Persisted (save v9); switchable in-game via setDifficulty. */
157	  difficulty: Difficulty;
158	  /** Hardcore world: forces Survival + Hard, locks both switchers, permadeath. Persisted (save v10); immutable. */
159	  hardcore: boolean;
160	  /** True once a hardcore run has ended in death — drives the spectator dead-world + Game Over screen. Persisted (save v10). */
161	  gameOver: boolean;
162	  /** True while flying (Creative toggle, always on for Spectator). Session-only, never serialized. */
163	  isFlying: boolean;
164	  hearts: number;
165	  hunger: number;
166	  /** Remaining breath, 0..MAX_OXYGEN. Session-only; refills out of water. */
167	  oxygen: number;
168	  /** Active status effects → remaining seconds. Persisted (save v6); cleared on death. */
169	  effects: Map<EffectId, number>;
170	  /** Banked XP points (XP_PER_LEVEL points = 1 level). Persisted (save v7); NOT cleared on death. */
171	  xp: number;
172	  isDead: boolean;
173	  respawnTimer: number;
174	  inventoryOpen: boolean;
175	  /** Crafting station whose recipes (or the enchanting panel) are unlocked while the inventory is open, or null. */
176	  craftingStation: "furnace" | "villager" | "brewing" | "enchanting" | "anvil" | "grindstone" | null;
177	  /** Chest contents (block-entities) keyed by the block's voxel index. */
178	  containers: Map<number, InventorySlot[]>;
179	  /** Lit TNT keyed by voxel index → seconds left on its fuse (session-only, never serialized). */
180	  primedTnt: Map<number, number>;
181	  /** Voxel index of the chest open in the inventory panel, or null. */
182	  openContainerIndex: number | null;
183	  /** Worldgen dungeon chest voxel indices (session; re-derived from the seed each load). */
184	  dungeonChestIndices: Set<number>;
185	  /** Worldgen dungeon spawner voxel indices (session; re-derived from the seed each load). */
186	  dungeonSpawnerIndices: Set<number>;
187	  /** Dungeon chests already opened/broken (persisted) — gates one-time lazy loot fill. */
188	  lootedDungeonChests: Set<number>;
189	  /** Frozen simulation behind the pause menu; only commands are processed. */
190	  paused: boolean;
191	  debugOpen: boolean;
192	  debugInfo: DebugInfo | null;
193	  cameraMode: CameraMode;
194	  capsActive: boolean;
195	  mobs: MobState[];
196	  nextMobId: number;
197	  thrownSpears: ThrownSpearState[];
198	  nextThrownSpearId: number;
199	  /** In-flight arrows (session-only; never serialized). */
200	  projectiles: ProjectileState[];
201	  nextProjectileId: number;
202	  /** The active fishing cast, or null when not fishing (session-only). */
203	  fishing: FishingState | null;
204	  dayClock: number;
205	  /** Derived from dayClock every tick; 0.04–1.0. */
206	  daylight: number;
207	  daylightPercent: number;
208	  /** Cosmetic, transient weather (never serialized). Drives precip + sky + audio. */
209	  weather: WeatherState;
210	  /** Seconds left in the sleep fade; > 0 freezes the sim until time skips. */
211	  sleepTimer: number;
212	  /** Bed respawn point (block coords), or null to respawn at a random land point. */
213	  spawnPoint: { x: number; y: number; z: number } | null;
214	  mining: MiningState;
215	  timers: GameTimers;
216	  /** Set when world geometry changed; the renderer rebuilds the mesh and clears it. */
217	  worldMeshDirty: boolean;
218	  /** True once the boss has been defeated — drives the one-shot victory screen (session-only). */
219	  victory: boolean;
220	};
221	
222	export function createTimers(): GameTimers {
223	  return {
224	    voidTimer: 0,
225	    regenTimer: 0,
226	    waterExposureTimer: 0,
227	    waterDamageTimer: 0,
228	    lavaBurnTimer: 0,
229	    lavaDamageTimer: 0,
230	    drownTimer: 0,
231	    starvationTimer: 0,
232	    sprintDistanceBudget: 0,
233	    walkDistanceBudget: 0,
234	    jumpBudget: 0,
235	    effectRegenTimer: 0,
236	    effectPoisonTimer: 0,
237	    stuckTimer: 0,
238	    hostileSpawnTimer: 0,
239	    spawnerTimer: 0,
240	    daylightHudTimer: 0,
241	    debugHudTimer: 0,
242	    randomTickTimer: 0,
243	    breedTimer: 0,
244	    spearThrowCooldown: 0,
245	    bowCooldownTimer: 0
246	  };
247	}
248	
249	/** Per-frame continuous input, owned by the input controller. */
250	export type FrameInput = {
251	  keys: ReadonlySet<string>;
252	  capsActive: boolean;
253	  leftMouseHeld: boolean;
254	  pointerLocked: boolean;
255	};
256	
257	export const IDLE_INPUT: FrameInput = {
258	  keys: new Set<string>(),
259	  capsActive: false,
260	  leftMouseHeld: false,
261	  pointerLocked: false
262	};
263	
264	/** The engine surface the UI may touch: intents in, save data out. */
265	export type GameApi = {
266	  dispatch(command: Command): void;
267	  serialize(): SaveData;
268	};
269	
270	/** Immutable view for the React UI, replaced only when a visible value changes. */
271	export type GameSnapshot = {
272	  /** Stable handle for dispatching intents; null until the engine exists. */
273	  api: GameApi | null;
274	  inventory: InventorySlot[];
275	  equippedArmor: EquippedArmor;
276	  selectedSlot: number;
277	  /** Current game mode — drives mode-specific HUD (hidden bars, palette, flying indicator). */
278	  gameMode: GameMode;
279	  /** Current difficulty — drives the pause-menu picker's active state. */
280	  difficulty: Difficulty;
281	  /** Hardcore world — disables the pause-menu mode/difficulty switchers and drives hardcore chrome (withered hearts). */
282	  hardcore: boolean;
283	  /** True after a hardcore death — drives the Game Over screen (spectating the dead world). */
284	  gameOver: boolean;
285	  /** True while flying — drives the flight indicator. */
286	  isFlying: boolean;
287	  hearts: number;
288	  hunger: number;
289	  /** Remaining breath, 0..MAX_OXYGEN — drives the bubble bar (hidden when full). */
290	  oxygen: number;
291	  daylightPercent: number;
292	  passiveCount: number;
293	  hostileCount: number;
294	  respawnSeconds: number;
295	  inventoryOpen: boolean;
296	  paused: boolean;
297	  debugOpen: boolean;
298	  debug: DebugInfo | null;
299	  cameraMode: CameraMode;
300	  /** Total defense points of equipped armor — drives the HUD armor bar. */
301	  armorPoints: number;
302	  capsActive: boolean;
303	  /** True during the sleep fade — drives the fade-to-black overlay. */
304	  sleeping: boolean;
305	  /** Open crafting station (gates smelting recipes, or opens the enchanting panel). */
306	  craftingStation: "furnace" | "villager" | "brewing" | "enchanting" | "anvil" | "grindstone" | null;
307	  /** Contents of the open chest, or null when no chest is open. */
308	  container: InventorySlot[] | null;
309	  /** Live boss health and navigation data, or null when no boss is alive — drives the boss HUD. */
310	  boss: ({ hpPercent: number } & BossTracking) | null;
311	  /** True after the boss is defeated — drives the victory screen. */
312	  victory: boolean;
313	  /** Active status effects (id + rounded seconds left) — drives the HUD effects readout. Ref-stable between content changes. */
314	  activeEffects: Array<{ id: EffectId; seconds: number }>;
315	  /** Current XP level and progress (0–1) toward the next — drives the HUD XP bar. */
316	  xpLevel: number;
317	  xpProgress: number;
318	};
319	
320	/** One-shot gameplay events for the shell (death screen, audio, ...). */
321	export type GameEvent =
322	  | { type: "died" }
323	  | { type: "gameOver" }
324	  | { type: "respawned" }
325	  | { type: "blockBroken"; blockId: BlockId; x: number; y: number; z: number }
326	  | { type: "blockPlaced"; blockId: BlockId; x: number; y: number; z: number }
327	  | { type: "playerHurt" }
328	  | { type: "ateFood" }
329	  | { type: "drankPotion" }
