1	import * as THREE from "three";
2	import { BlockId, type WorldType } from "@/lib/world";
3	import type { GameMode } from "./gameModes";
4	import type { Difficulty } from "./difficulties";
5	
6	export type ItemKind = "block" | "weapon" | "tool" | "armor" | "food" | "material";
7	export type ArmorSlot = "helmet" | "face_mask" | "neck_protection" | "chestplate" | "leggings" | "boots";
8	/** The worn armor pieces, one per slot — the actual item instance (or null). Equipping moves the piece here, out of the inventory. */
9	export type EquippedArmor = Record<ArmorSlot, InventorySlot | null>;
10	
11	/** A timed status effect on the player. Positive effects come from potions; poison is a hazard. */
12	export type EffectId = "speed" | "strength" | "regeneration" | "fire_resistance" | "water_breathing" | "haste" | "resistance" | "jump_boost" | "poison";
13	
14	/** The effect a drinkable potion applies, with how long it lasts. */
15	export type ItemEffect = { id: EffectId; durationSeconds: number };
16	
17	/** A gear enchantment applied at the enchanting table; each maps to one combat/mining/durability seam. */
18	export type EnchantmentId =
19	  | "sharpness"
20	  | "protection"
21	  | "efficiency"
22	  | "unbreaking"
23	  | "mending"
24	  | "power"
25	  | "punch"
26	  | "knockback"
27	  | "looting"
28	  | "fortune"
29	  | "feather_falling";
30	
31	/** A per-item-instance enchantment and its level. */
32	export type Enchantment = { id: EnchantmentId; level: number };
33	
34	export type ItemDef = {
35	  id: string;
36	  label: string;
37	  kind: ItemKind;
38	  blockId?: BlockId;
39	  attack?: number;
40	  meleeReach?: number;
41	  throwDamage?: number;
42	  minePower?: number;
43	  mineTier?: number;
44	  armorSlot?: ArmorSlot;
45	  defense?: number;
46	  maxDurability?: number;
47	  /** Hunger points restored when eaten (food items only). */
48	  hunger?: number;
49	  /** The status effect this potion applies when drunk (potion items only). */
50	  effect?: ItemEffect;
51	};
52	
53	export type InventorySlot = {
54	  id: string | null;
55	  label: string;
56	  kind: ItemKind | null;
57	  count: number;
58	  blockId?: BlockId;
59	  attack?: number;
60	  meleeReach?: number;
61	  throwDamage?: number;
62	  minePower?: number;
63	  mineTier?: number;
64	  armorSlot?: ArmorSlot;
65	  defense?: number;
66	  durability?: number;
67	  maxDurability?: number;
68	  hunger?: number;
69	  effect?: ItemEffect;
70	  /** Per-instance enchantments (durable gear only) — applied at the enchanting table. */
71	  enchantments?: Enchantment[];
72	  /** Player-set name from the anvil (durable gear only); falls back to `label` for display. */
73	  customName?: string;
74	};
75	
76	export type Recipe = {
77	  id: string;
78	  label: string;
79	  cost: Array<{ slotId: string; count: number }>;
80	  result: { slotId: string; count: number };
81	  /**
82	   * Station required for this recipe; omitted means the basic crafting grid.
83	   * "furnace" smelts; "villager" is a trade offer, unlocked while trading with a
84	   * villager; "brewing" is a potion recipe, unlocked at a brewing stand.
