1	/**
2	 * Progression meta: gameplay statistics (running counters) and the advancement
3	 * registry. Everything funnels through `recordEvent`, called once per emitted
4	 * GameEvent from the engine's single emit chokepoint, plus `recordTick` for the
5	 * per-frame display counters (distance travelled, play time).
6	 *
7	 * Pure and declarative: it only reads/writes `state.stats` and
8	 * `state.advancements`, so it's trivially unit-testable without booting an
9	 * engine. `evaluateAdvancements` is a pure function of the current stats.
10	 */
11	import { BlockId } from "@/lib/world";
12	import { HOSTILE_MOB_KINDS } from "@/lib/game/mobs";
13	import { RECIPES } from "@/lib/game/recipes";
14	import type { GameEvent, GameState } from "../state";
15	
16	/** How a Statistics-tab value is rendered (a plain count vs. blocks travelled vs. a clock). */
17	export type StatFormat = "count" | "distance" | "duration";
18	
19	/** Display metadata for one statistic shown in the Statistics tab. */
20	export type StatMeta = { id: string; label: string; format: StatFormat };
21	
22	/**
23	 * The statistics surfaced (in order) in the Statistics tab. recordEvent/recordTick
24	 * may bump counters not listed here (the per-recipe `crafted_<id>` and the per-block
25	 * `*_mined` counters that drive advancements) — those stay out of the display.
26	 */
27	export const STATS: readonly StatMeta[] = [
28	  { id: "play_time", label: "Time Played", format: "duration" },
29	  { id: "distance_walked", label: "Distance Travelled", format: "distance" },
30	  { id: "blocks_mined", label: "Blocks Mined", format: "count" },
31	  { id: "logs_chopped", label: "Logs Chopped", format: "count" },
32	  { id: "diamond_ore_mined", label: "Diamond Ore Mined", format: "count" },
33	  { id: "hostiles_killed", label: "Monsters Slain", format: "count" },
34	  { id: "animals_bred", label: "Animals Bred", format: "count" },
35	  { id: "items_crafted", label: "Items Crafted", format: "count" },
36	  { id: "items_enchanted", label: "Items Enchanted", format: "count" },
37	  { id: "potions_drunk", label: "Potions Drunk", format: "count" },
38	  { id: "fish_caught", label: "Fish Caught", format: "count" },
39	  { id: "arrows_fired", label: "Arrows Fired", format: "count" },
40	  { id: "villager_trades", label: "Villager Trades", format: "count" },
41	  { id: "jumps", label: "Jumps", format: "count" },
42	  { id: "deaths", label: "Deaths", format: "count" }
43	];
44	
45	// Per-block "mined" counters. blockBroken always bumps the `blocks_mined` total;
46	// these targeted counters drive the mining / farming advancements.
47	const MINED_STAT_BY_BLOCK: Partial<Record<BlockId, string>> = {
48	  [BlockId.Wood]: "logs_chopped",
49	  [BlockId.Stone]: "stone_mined",
50	  [BlockId.CoalOre]: "coal_ore_mined",
51	  [BlockId.SliverOre]: "sliver_ore_mined",
52	  [BlockId.GoldOre]: "gold_ore_mined",
53	  [BlockId.RubyOre]: "ruby_ore_mined",
54	  [BlockId.SapphireOre]: "sapphire_ore_mined",
55	  [BlockId.DiamondOre]: "diamond_ore_mined",
56	  [BlockId.WheatStage3]: "wheat_harvested"
57	};
58	
59	const RECIPE_BY_ID = new Map(RECIPES.map((recipe) => [recipe.id, recipe]));
60	
61	function bump(state: GameState, id: string, by = 1): void {
62	  state.stats.set(id, (state.stats.get(id) ?? 0) + by);
63	}
64	
65	/**
66	 * Folds one gameplay event into the stat counters. Called for every event the
67	 * engine emits (the `advancementUnlocked` event is guarded out upstream so this
68	 * never recurses). Unknown / irrelevant event types are simply ignored.
69	 */
70	export function recordEvent(state: GameState, event: GameEvent): void {
71	  switch (event.type) {
72	    case "blockBroken": {
73	      bump(state, "blocks_mined");
74	      const mined = MINED_STAT_BY_BLOCK[event.blockId];
75	      if (mined) bump(state, mined);
76	      break;
77	    }
78	    case "mobDied":
79	      if (HOSTILE_MOB_KINDS.has(event.kind)) bump(state, "hostiles_killed");
80	      break;
81	    case "mobBred":
82	      bump(state, "animals_bred");
83	      break;
84	    case "enchanted":
85	      bump(state, "items_enchanted");
86	      break;
87	    case "drankPotion":
88	      bump(state, "potions_drunk");
89	      break;
90	    case "fishingCaught":
91	      bump(state, "fish_caught");
92	      break;
93	    case "bowFired":
94	      bump(state, "arrows_fired");
95	      break;
96	    case "sleepStarted":
97	      bump(state, "sleeps");
98	      break;
99	    case "bossDefeated":
100	      bump(state, "boss_defeated");
101	      break;
102	    case "died":
103	      bump(state, "deaths");
104	      break;
105	    case "jumped":
106	      bump(state, "jumps");
107	      break;
108	    case "crafted": {
109	      const recipe = RECIPE_BY_ID.get(event.recipeId);
110	      if (!recipe) break;
111	      bump(state, "items_crafted");
112	      bump(state, `crafted_${recipe.id}`);
113	      // "Tool Up" wants any pickaxe (7 tiers, 7 recipes), so aggregate them.
114	      if (recipe.result.slotId.endsWith("_pickaxe")) bump(state, "pickaxes_crafted");
115	      // A villager trade is a station-gated recipe — drive the trade advancement.
116	      if (recipe.station === "villager") bump(state, "villager_trades");
117	      break;
118	    }
119	  }
120	}
121	
122	/**
123	 * Accumulates the per-frame display counters: seconds of active play and blocks
124	 * travelled. No advancement depends on these, so they stay out of recordEvent
125	 * (and the unlock path) — the engine calls this each active step.
126	 */
127	export function recordTick(state: GameState, dt: number, horizontalDistance: number): void {
128	  bump(state, "play_time", dt);
129	  bump(state, "distance_walked", horizontalDistance);
130	}
131	
132	// --- Advancements ---
133	
134	/** The section an advancement falls under in the Advancements tab grid. */
135	export type AdvancementCategory = "Mining" | "Crafting" | "Combat" | "Farming" | "Magic" | "Adventure";
136	
137	/** Fixed display order for the Advancements grid; empty categories are skipped. */
138	export const ADVANCEMENT_CATEGORY_ORDER: readonly AdvancementCategory[] = ["Mining", "Crafting", "Combat", "Farming", "Magic", "Adventure"];
139	
140	/**
141	 * One advancement. Unlock is uniform: `state.stats.get(stat) >= threshold`, so
142	 * the whole set is a declarative table — adding one is a single row, no logic.
143	 * `icon` is an existing item/block id rendered through `itemIconUrl` (zero new
144	 * assets); each maps to a counter that `recordEvent` produces.
145	 */
146	export type Advancement = {
147	  id: string;
148	  title: string;
149	  description: string;
150	  icon: string;
151	  category: AdvancementCategory;
152	  stat: string;
153	  threshold: number;
154	};
155	
156	/**
157	 * The tight, flat set of advancements — one per major system the player can
158	 * engage. Thresholds are 1 (the goal is to guide a first encounter with each
159	 * system); they're declarative, so tuning is a one-field edit.
160	 */
161	export const ADVANCEMENTS: readonly Advancement[] = [
162	  { id: "getting_wood", title: "Getting Wood", description: "Chop down a log.", icon: "wood", category: "Mining", stat: "logs_chopped", threshold: 1 },
163	  { id: "stone_age", title: "Stone Age", description: "Mine a block of stone.", icon: "stone", category: "Mining", stat: "stone_mined", threshold: 1 },
164	  { id: "ironish", title: "Iron-ish", description: "Mine sliver ore.", icon: "sliver_ore", category: "Mining", stat: "sliver_ore_mined", threshold: 1 },
