53	  debug: null,
54	  cameraMode: "first",
55	  armorPoints: 0,
56	  capsActive: false,
57	  sleeping: false,
58	  craftingStation: null,
59	  container: null,
60	  boss: null,
61	  victory: false,
62	  activeEffects: [],
63	  xpLevel: 0,
64	  xpProgress: 0
65	};
66	
67	const noopSubscribe = () => () => {};
68	
69	type GameContext = { engine: GameEngine; node: HTMLDivElement };
70	
71	// Debug/test handle: lets the browser console and the Playwright E2E suite
72	// inspect the live simulation (single-player client game — nothing to protect).
73	declare global {
74	  interface Window {
75	    __monecraft?: { engine: GameEngine; renderer: GameRenderer; input: InputController; audio: AudioDirector };
76	  }
77	}
78	
79	function persistGame(api: GameApi, saveKey: string, onMessage: (text: string) => void): void {
80	  try {
81	    writeSave(saveKey, api.serialize());
82	    onMessage("Saved");
83	  } catch {
84	    onMessage("Save failed");
85	  }
86	}
87	
88	/**
89	 * One mounted game = one world played by one profile. The owning shell remounts
90	 * this hook (via a React `key` on the world id) to switch worlds, so the
91	 * per-world save key and the profile are fixed for the hook's lifetime.
92	 */
93	export type UseMinecraftGameOptions = {
94	  world: WorldMeta;
95	  profile: Profile;
96	  /** Leave this world and return to the world list (the shell unmounts us). */
97	  onQuitToWorlds: () => void;
98	  /** Re-read this world from disk by forcing a fresh mount (used by Load/Reset). */
99	  onReloadWorld: () => void;
100	};
101	
102	export function useMinecraftGame(opts: UseMinecraftGameOptions) {
103	  // The owning shell keys this hook by world id, so the world is fixed for the
104	  // mount's life; capturing it once in refs lets the long-lived rAF/autosave
105	  // effect read the save key and seed without re-subscribing.
106	  const saveKeyRef = useRef(worldSaveKey(opts.world.id));
107	  const worldSeedRef = useRef(opts.world.seed);
108	  const worldTypeRef = useRef(opts.world.worldType);
109	  const worldModeRef = useRef(opts.world.gameMode);
110	  const worldDifficultyRef = useRef(opts.world.difficulty);
111	  const worldHardcoreRef = useRef(opts.world.hardcore);
112	  const [ctx, setCtx] = useState<GameContext | null>(null);
113	  const [locked, setLocked] = useState(false);
114	  const [saveMessage, setSaveMessage] = useState("");
115	  const [rendererError, setRendererError] = useState<string | null>(null);
116	  const [audioSettings, setAudioSettings] = useState<AudioSettings>(DEFAULT_AUDIO_SETTINGS);
117	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
118	  const minimapNodeRef = useRef<HTMLDivElement | null>(null);
119	  const audioRef = useRef<AudioDirector | null>(null);
120	  // The rAF effect must not re-run on volume tweaks — it reads through a ref.
121	  const audioSettingsRef = useRef(audioSettings);
122	  const [skinId, setSkinId] = useState<SkinId>(opts.profile.skinId);
123	  const skinIdRef = useRef(skinId);
124	  const rendererRef = useRef<GameRenderer | null>(null);
125	  // Pending UI timers (flash messages, world-reload defers) so they can be
126	  // cancelled on unmount instead of firing setState/onReloadWorld after teardown.
127	  const pendingTimeoutsRef = useRef<Set<number>>(new Set());
128	  // Set by Load/Reset before they force a remount: those want to re-read (or
129	  // discard) the on-disk save, so the unmount must NOT persist the live state
130	  // over it. Consumed once by the cleanup; every other unmount saves.
131	  const skipUnmountSaveRef = useRef(false);
132	
133	  // Audio is a global preference loaded after mount: render never touches
134	  // localStorage (SSR), and the setState hops a microtask like the
135	  // renderer-error report. This effect runs before the renderer effect (ctx is
136	  // set by a callback ref in a later commit), so the ref is populated by the
137	  // time either exists. The skin is per-profile and comes in via opts, not here.
138	  useEffect(() => {
139	    const stored = readAudioSettings();
140	    audioSettingsRef.current = stored;
141	    audioRef.current?.setSettings(stored);
142	    queueMicrotask(() => setAudioSettings(stored));
143	  }, []);
144	
145	  const updateAudioSettings = useCallback((partial: Partial<AudioSettings>) => {
146	    const next = { ...audioSettingsRef.current, ...partial };
147	    audioSettingsRef.current = next;
148	    setAudioSettings(next);
149	    writeAudioSettings(next);
150	    audioRef.current?.setSettings(next);
151	  }, []);
152	
153	  const updateSkin = useCallback(
154	    (id: SkinId) => {
155	      skinIdRef.current = id;
156	      setSkinId(id);
157	      setProfileSkin(opts.profile.id, id);
158	      rendererRef.current?.setPlayerSkin(getSkinPreset(id).palette);
159	    },
160	    [opts.profile.id]
161	  );
162	
163	  // Callback ref: the engine boots as soon as the canvas mount exists. A ref
164	  // callback runs during commit, where side effects and setState are legal.
165	  const attachMount = useCallback((node: HTMLDivElement | null) => {
166	    if (!node) {
167	      setCtx(null);
168	      return;
169	    }
170	    // A saved blob carries its own seed + type + mode + difficulty (engine prefers
171	    // them); a fresh world (no blob yet) boots from the world's stored values.
172	    setCtx({
173	      engine: new GameEngine({
174	        save: readSave(saveKeyRef.current),
175	        seed: worldSeedRef.current,
176	        worldType: worldTypeRef.current,
177	        gameMode: worldModeRef.current,
178	        difficulty: worldDifficultyRef.current,
179	        hardcore: worldHardcoreRef.current
180	      }),
181	      node
182	    });
183	  }, []);
184	
185	  // The minimap container mounts independently of the canvas; the rAF loop
186	  // below picks it up lazily once both exist.
187	  const attachMinimap = useCallback((node: HTMLDivElement | null) => {
188	    minimapNodeRef.current = node;
189	  }, []);
190	
191	  const engine = ctx?.engine ?? null;
192	  const subscribe = useMemo(() => engine?.subscribe ?? noopSubscribe, [engine]);
193	  const getSnapshot = useMemo(() => engine?.getSnapshot ?? (() => PRE_MOUNT_SNAPSHOT), [engine]);
194	  const getServerSnapshot = useCallback(() => PRE_MOUNT_SNAPSHOT, []);
195	  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
196	
197	  // Tracks each timer so unmount can cancel it; the timer also self-removes when
198	  // it fires so the set never grows unbounded.
199	  const scheduleTimeout = useCallback((fn: () => void, ms: number) => {
200	    const id = window.setTimeout(() => {
201	      pendingTimeoutsRef.current.delete(id);
202	      fn();
203	    }, ms);
204	    pendingTimeoutsRef.current.add(id);
205	  }, []);
206	
207	  useEffect(
208	    () => () => {
209	      for (const id of pendingTimeoutsRef.current) window.clearTimeout(id);
210	      pendingTimeoutsRef.current.clear();
211	    },
212	    []
213	  );
214	
215	  const flashMessage = useCallback(
216	    (text: string, durationMs = 1200) => {
217	      setSaveMessage(text);
218	      scheduleTimeout(() => setSaveMessage(""), durationMs);
219	    },
220	    [scheduleTimeout]
221	  );
222	
223	  useEffect(() => {
224	    if (!ctx) return;
225	    const { engine: gameEngine, node } = ctx;
226	
227	    const created = GameRenderer.create(node);
228	    if (!created.ok) {
229	      // Microtask: reporting an init failure from inside the effect body
230	      // would count as a cascading synchronous setState.
231	      queueMicrotask(() => setRendererError(created.error));
232	      return;
233	    }
234	    const renderer = created.renderer;
235	    canvasRef.current = renderer.domElement;
236	    rendererRef.current = renderer;
237	    // Before the first rAF, so no frame can ever show the default palette.
238	    renderer.setPlayerSkin(getSkinPreset(skinIdRef.current).palette);
239	
240	    const audio = createAudioDirector();
241	    audio.setSettings(audioSettingsRef.current);
242	    audioRef.current = audio;
243	    const input = createInputController({
244	      canvas: renderer.domElement,
245	      engine: gameEngine,
246	      onResize: () => renderer.handleResize(),
247	      onLockChange: (isLocked) => {
248	        // Pointer-lock acquisition is itself a user gesture — a safe unlock
249	        // point, and it re-resumes a context suspended by the browser.
250	        if (isLocked) audio.unlock();
251	        setLocked(isLocked);
252	      }
253	    });
254	
255	    // Autoplay policy: the AudioContext may only start inside a user gesture.
256	    const unlockAudio = () => audio.unlock();
257	    document.addEventListener("mousedown", unlockAudio);
258	    document.addEventListener("keydown", unlockAudio);
259	
260	    // The save key is fixed for the mount's life (the shell keys this hook by
261	    // world id), so capture it once — also keeps it out of the cleanup's ref read.
262	    const saveKey = saveKeyRef.current;
263	    const autoSave = () => persistGame(gameEngine, saveKey, flashMessage);
264	    const autoSaveId = window.setInterval(autoSave, AUTOSAVE_INTERVAL_MS);
265	    window.addEventListener("beforeunload", autoSave);
266	
267	    window.__monecraft = { engine: gameEngine, renderer, input, audio };
268	
269	    let minimap: MinimapRenderer | null = null;
270	    let last = performance.now();
271	    let animationFrame = 0;
272	    // Catch-up stepping: a slow frame (software GL, busy machine) can take far
273	    // longer than one 50ms step, and a single clamped step would run the
274	    // simulation in slow motion. Bounded substeps keep sim time tracking wall
275	    // time; the cap bounds work per frame and quietly drops time beyond it
276	    // (e.g. after a background-tab stall).
277	    const MAX_STEP_SECONDS = 0.05;
278	    const MAX_SUBSTEPS = 5;
279	    let pendingSeconds = 0;
280	    const clock = () => {
281	      const now = performance.now();
282	      pendingSeconds = Math.min(pendingSeconds + (now - last) / 1000, MAX_STEP_SECONDS * MAX_SUBSTEPS);
283	      last = now;
284	
285	      let frameSeconds = 0;
286	      while (pendingSeconds > 0) {
287	        const dt = Math.min(pendingSeconds, MAX_STEP_SECONDS);
288	        gameEngine.step(dt, input.input);
289	        pendingSeconds -= dt;
290	        frameSeconds += dt;
291	      }
292	
293	      for (const event of gameEngine.consumeEvents()) {
294	        if (event.type === "died" || event.type === "bossDefeated" || event.type === "gameOver") {
295	          // Free the cursor so the death/victory/game-over button is clickable; the
296	          // pause command ignores those states, so the lock-loss won't open the menu too.
297	          input.clearKeys();
298	          if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
299	        }
300	        // Hardcore permadeath is permanent — persist it now so closing the tab right
301	        // after death still reloads the dead world spectating (not a fresh run).
302	        if (event.type === "gameOver") persistGame(gameEngine, saveKey, () => {});
303	        if (event.type === "respawned") input.clearKeys();
304	        if (event.type === "attackSwung") renderer.triggerSwing();
305	        if (event.type === "openedStation" || event.type === "openedContainer") {
306	          // A furnace/chest opened the inventory from a mouse click — release the
307	          // keys and pointer lock the same way KeyI does on the DOM side.
308	          input.clearKeys();
309	          if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
310	        }
311	        if (event.type === "breakBlocked") {
312	          flashMessage("Not enough room to empty the chest");
313	        }
314	        if (event.type === "sleepDenied") {
315	          flashMessage(event.reason === "daylight" ? "You can only sleep at night" : "Monsters are nearby");
316	        }
317	        if (event.type === "pickedUp") {
318	          flashMessage(event.items.map((drop) => `+${drop.count} ${ITEM_DEF_BY_ID[drop.itemId]?.label ?? drop.itemId}`).join(", "));
319	        }
320	        if (event.type === "fishingCaught") {
321	          // Common fish/junk stay diegetic (splash + sound); only the rare treasure earns a toast.
322	          const treasure = event.items.find((drop) => drop.itemId === "emerald");
323	          if (treasure) flashMessage(`Reeled in treasure: ${ITEM_DEF_BY_ID[treasure.itemId]?.label ?? treasure.itemId}!`);
324	        }
325	        if (event.type === "summonFailed") {
326	          flashMessage("The totem lies dormant — a beast already walks");
327	        }
328	        renderer.handleEvent(event, gameEngine.state);
329	        audio.handleEvent(event);
330	      }
331	
332	      if (!minimap && minimapNodeRef.current) minimap = createMinimapRenderer(minimapNodeRef.current);
333	      // The minimap must read worldMeshDirty before renderer.sync clears it.
334	      minimap?.sync(gameEngine.state, now);
335	      renderer.sync(gameEngine.state, now);
336	      audio.sync(gameEngine.state, frameSeconds);
337	      renderer.render();
338	      animationFrame = requestAnimationFrame(clock);
339	    };
340	    animationFrame = requestAnimationFrame(clock);
341	
342	    return () => {
343	      // Persist on teardown so progress survives an unmount that fires no
344	      // `beforeunload` — most importantly dev Fast Refresh, which remounts the
345	      // component (losing everything since the last 15s autosave) without a page
346	      // reload. Silent (no "Saved" toast) and skipped for Load/Reset, which
347	      // intentionally re-read or discard the on-disk save.
348	      if (skipUnmountSaveRef.current) skipUnmountSaveRef.current = false;
349	      else persistGame(gameEngine, saveKey, () => {});
350	      delete window.__monecraft;
351	      canvasRef.current = null;
352	      rendererRef.current = null;
353	      minimap?.dispose();
354	      cancelAnimationFrame(animationFrame);
355	      window.clearInterval(autoSaveId);
356	      window.removeEventListener("beforeunload", autoSave);
357	      document.removeEventListener("mousedown", unlockAudio);
358	      document.removeEventListener("keydown", unlockAudio);
359	      audioRef.current = null;
360	      audio.dispose();
361	      input.dispose();
362	      document.exitPointerLock();
363	      renderer.dispose();
364	    };
365	  }, [ctx, flashMessage]);
366	
367	  // Re-locking can legitimately reject (e.g. Chrome's cooldown right after
368	  // Escape); the player just clicks the canvas to lock again.
369	  const requestPointerLock = useCallback(() => {
370	    const canvas = canvasRef.current;
371	    if (canvas) Promise.resolve(canvas.requestPointerLock()).catch(() => {});
372	  }, []);
373	
374	  return {
375	    attachMount,
376	    attachMinimap,
377	    locked,
378	    rendererError,
379	    gameMode: snapshot.gameMode,
380	    difficulty: snapshot.difficulty,
381	    hardcore: snapshot.hardcore,
382	    gameOver: snapshot.gameOver,
383	    giveCreativeItem: (itemId: string) => engine?.dispatch({ type: "creativeGiveItem", itemId }),
384	    setGameMode: (mode: GameMode) => engine?.dispatch({ type: "setGameMode", mode }),
385	    setDifficulty: (difficulty: Difficulty) => engine?.dispatch({ type: "setDifficulty", difficulty }),
386	    selectedSlot: snapshot.selectedSlot,
387	    setSelectedSlot: (index: number) => engine?.dispatch({ type: "selectSlot", index }),
388	    capsActive: snapshot.capsActive,
389	    inventoryOpen: snapshot.inventoryOpen,
390	    inventory: snapshot.inventory,
391	    equippedArmor: snapshot.equippedArmor,
392	    armorPoints: snapshot.armorPoints,
393	    hearts: snapshot.hearts,
394	    hunger: snapshot.hunger,
395	    oxygen: snapshot.oxygen,
396	    daylightPercent: snapshot.daylightPercent,
397	    passiveCount: snapshot.passiveCount,
398	    hostileCount: snapshot.hostileCount,
399	    respawnSeconds: snapshot.respawnSeconds,
400	    paused: snapshot.paused,
401	    sleeping: snapshot.sleeping,
402	    craftingStation: snapshot.craftingStation,
403	    container: snapshot.container,
404	    boss: snapshot.boss,
405	    victory: snapshot.victory,
406	    activeEffects: snapshot.activeEffects,
407	    xpLevel: snapshot.xpLevel,
408	    xpProgress: snapshot.xpProgress,
409	    debugOpen: snapshot.debugOpen,
410	    debug: snapshot.debug,
411	    saveMessage,
412	    audioSettings,
413	    updateAudioSettings,
414	    skinId,
415	    updateSkin,
416	    hotbarSlots: HOTBAR_SLOTS,
417	    recipes: RECIPES,
418	    maxHearts: MAX_HEARTS,
419	    maxHunger: MAX_HUNGER,
420	    maxOxygen: MAX_OXYGEN,
421	    canCraft: (recipe: Recipe) => inv.canCraft(snapshot.inventory, recipe),
422	    craft: (recipe: Recipe) => engine?.dispatch({ type: "craft", recipeId: recipe.id }),
423	    enchant: (id: EnchantmentId) => engine?.dispatch({ type: "enchant", enchant: id }),
424	    anvilCombine: () => engine?.dispatch({ type: "anvilCombine" }),
425	    anvilRepair: () => engine?.dispatch({ type: "anvilRepair" }),
426	    anvilRename: (name: string) => engine?.dispatch({ type: "anvilRename", name }),
427	    grindstoneStrip: () => engine?.dispatch({ type: "grindstoneStrip" }),
428	    swapInventorySlots: (from: number, to: number) => engine?.dispatch({ type: "swapSlots", from, to }),
429	    moveStack: (from: number, to: number) => engine?.dispatch({ type: "moveStack", from, to }),
430	    toggleEquipArmor: (index: number) => engine?.dispatch({ type: "toggleEquipArmor", index }),
431	    unequipArmor: (slot: ArmorSlot) => engine?.dispatch({ type: "unequipArmor", slot }),
432	    resumeNow: () => {
433	      engine?.dispatch({ type: "resume" });
434	      requestPointerLock();
435	    },
436	    respawnNow: () => engine?.dispatch({ type: "respawn" }),
437	    dismissVictory: () => engine?.dispatch({ type: "dismissVictory" }),
438	    saveNow: () => {
439	      if (engine) persistGame(engine, saveKeyRef.current, flashMessage);
440	    },
441	    loadNow: () => {
442	      if (!readSave(saveKeyRef.current)) {
443	        flashMessage("No save found", 1400);
444	        return;
445	      }
446	      flashMessage("Loaded");
447	      // Remount this world (no page reload) so the engine re-reads the saved blob.
448	      // Suppress the unmount save so it can't overwrite the blob we're reloading.
449	      skipUnmountSaveRef.current = true;
450	      scheduleTimeout(() => opts.onReloadWorld(), 120);
451	    },
452	    resetNow: () => {
453	      try {
454	        localStorage.removeItem(saveKeyRef.current);
455	        setSaveMessage("Resetting...");
456	        // Remount with no blob: the fresh engine regenerates from the stored seed.
457	        // Suppress the unmount save so it can't rewrite the blob we just removed.
458	        skipUnmountSaveRef.current = true;
459	        scheduleTimeout(() => opts.onReloadWorld(), 500);
460	      } catch {
461	        flashMessage("Reset failed");
462	      }
463	    },
464	    quitToWorlds: () => {
465	      // The autosave interval is cleared on unmount and beforeunload won't fire
466	      // on an in-app navigation, so persist synchronously before leaving.
467	      if (engine) persistGame(engine, saveKeyRef.current, flashMessage);
468	      opts.onQuitToWorlds();
469	    }
470	  };
471	}
