1	/* Full-screen overlays: pause menu, F3 debug readout, click-to-play hint. */
2	
3	/* Shared dimmer behind any open menu (inventory or pause). Sits above the
4	   canvas/hotbar (z 4) and below the inventory (z 6) and pause menu (z 9), so a
5	   single element darkens the frozen world without double-dimming. */
6	.menu-backdrop {
7	  position: absolute;
8	  inset: 0;
9	  z-index: 5;
10	  background: rgba(0, 0, 0, 0.55);
11	  animation: mc-fade-in 140ms ease-out;
12	}
13	
14	.pause-overlay {
15	  position: absolute;
16	  inset: 0;
17	  z-index: 9;
18	  display: flex;
19	  align-items: center;
20	  justify-content: center;
21	  animation: mc-fade-in 140ms ease-out;
22	}
23	
24	.pause-menu {
25	  display: grid;
26	  gap: 8px;
27	  width: min(92vw, 320px);
28	  justify-items: stretch;
29	  /* The menu can grow taller than the viewport (mode + skin + controls
30	     sections); scroll inside it so the top buttons never clip off-screen. */
31	  max-height: 100vh;
32	  overflow-y: auto;
33	  padding: 6px 0;
34	}
35	
36	.pause-title {
37	  text-align: center;
38	  color: var(--mc-text-light);
39	  font-size: 22px;
40	  font-weight: 700;
41	  text-shadow: var(--mc-text-shadow);
42	  margin-bottom: 10px;
43	}
44	
45	/* Tabbed pause menu: a Game / Options / Controls selector over a single panel. */
46	.pause-tabs {
47	  display: grid;
48	  grid-template-columns: repeat(3, 1fr);
49	  gap: 6px;
50	  margin-top: 4px;
51	}
52	
53	.pause-tab {
54	  padding: 7px 8px;
55	  font-size: 12px;
56	}
57	
58	.pause-tab[aria-pressed="true"] {
59	  border-color: #f0be3c;
60	  outline: 1px solid rgba(240, 190, 60, 0.6);
61	}
62	
63	.pause-panel {
64	  display: grid;
65	  gap: 8px;
66	}
67	
68	.mc-button {
69	  padding: 9px 16px;
70	  font-family: inherit;
71	  font-size: 14px;
72	  font-weight: 700;
73	  color: var(--mc-text-light);
74	  text-shadow: var(--mc-text-shadow);
75	  background: var(--mc-tile-button), var(--mc-button);
76	  border-style: solid;
77	  border-width: 2px;
78	  border-color: #a8a8a8 #2c2c2c #2c2c2c #a8a8a8;
79	  outline: 2px solid rgba(0, 0, 0, 0.85);
80	  cursor: pointer;
81	  user-select: none;
82	  transition: background-color 80ms ease;
83	}
84	
85	.mc-button:hover,
86	.mc-button:focus-visible {
87	  background: var(--mc-button-hover);
88	  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
89	}
90	
91	.mc-button:active {
92	  border-color: #2c2c2c #a8a8a8 #a8a8a8 #2c2c2c;
93	  transform: translateY(1px);
94	}
95	
96	.mc-button:disabled {
97	  opacity: 0.55;
98	  cursor: not-allowed;
99	}
100	
101	.mc-button.danger {
102	  background: #8c3a34;
103	  border-color: #c98179 #4a1713 #4a1713 #c98179;
104	}
105	
106	.pause-reset-row {
107	  display: grid;
108	  grid-template-columns: 1fr 1fr;
109	  gap: 8px;
110	}
111	
112	.pause-sound {
113	  display: grid;
114	  gap: 8px;
115	  margin-top: 4px;
116	}
117	
118	.pause-sound-row {
119	  display: grid;
120	  grid-template-columns: 64px 1fr;
121	  align-items: center;
122	  gap: 10px;
123	  color: var(--mc-text-light);
124	  font-size: 13px;
125	  font-weight: 700;
126	  text-shadow: var(--mc-text-shadow);
127	}
128	
129	.pause-skins {
130	  display: grid;
131	  gap: 6px;
132	  margin-top: 4px;
133	}
134	
135	.pause-skins-title {
136	  color: var(--mc-text-light);
137	  font-size: 13px;
138	  font-weight: 700;
139	  text-shadow: var(--mc-text-shadow);
140	}
141	
142	.pause-skins-grid {
143	  display: grid;
144	  grid-template-columns: repeat(3, 1fr);
145	  gap: 6px;
146	}
147	
148	.skin-swatch {
149	  display: flex;
150	  flex-direction: column;
151	  align-items: center;
152	  gap: 3px;
153	  padding: 6px 4px;
154	  font-family: inherit;
155	  font-size: 11px;
156	  font-weight: 700;
157	  color: var(--mc-text-light);
158	  text-shadow: var(--mc-text-shadow);
159	  background: var(--mc-tile-button), var(--mc-button);
160	  border-style: solid;
161	  border-width: 2px;
162	  border-color: #a8a8a8 #2c2c2c #2c2c2c #a8a8a8;
163	  cursor: pointer;
164	  user-select: none;
165	}
166	
167	.skin-swatch:hover,
168	.skin-swatch:focus-visible {
169	  background: var(--mc-button-hover);
170	  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
171	}
172	
173	.skin-swatch[aria-pressed="true"] {
174	  background: var(--mc-button-hover);
175	  border-color: #f0be3c;
176	  outline: 1px solid rgba(240, 190, 60, 0.6);
177	}
178	
179	.pause-modes {
180	  margin-bottom: 6px;
181	}
182	
183	.pause-modes-grid {
184	  display: grid;
185	  grid-template-columns: 1fr 1fr;
186	  gap: 6px;
187	  margin-top: 4px;
188	}
189	
190	.mode-option[aria-pressed="true"] {
191	  border-color: #f0be3c;
192	  outline: 1px solid rgba(240, 190, 60, 0.6);
193	}
194	
195	.mc-slider {
196	  appearance: none;
197	  width: 100%;
198	  height: 18px;
199	  margin: 0;
200	  background: var(--mc-tile-button), var(--mc-button);
201	  border-style: solid;
202	  border-width: 2px;
203	  border-color: #2c2c2c #a8a8a8 #a8a8a8 #2c2c2c;
204	  outline: 2px solid rgba(0, 0, 0, 0.85);
205	  cursor: pointer;
206	}
207	
208	.mc-slider:focus-visible {
209	  background: var(--mc-button-hover);
210	  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
211	}
212	
213	.mc-slider::-webkit-slider-thumb {
214	  appearance: none;
215	  width: 12px;
216	  height: 18px;
217	  background: var(--mc-button-hover);
218	  border-style: solid;
219	  border-width: 2px;
220	  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
221	}
222	
223	.mc-slider::-moz-range-thumb {
224	  width: 12px;
225	  height: 18px;
226	  border-radius: 0;
227	  background: var(--mc-button-hover);
228	  border-style: solid;
229	  border-width: 2px;
230	  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
231	}
232	
233	.pause-save-message {
234	  text-align: center;
235	  color: #aef79f;
236	  font-size: 13px;
237	  font-weight: 700;
238	  text-shadow: var(--mc-text-shadow);
239	}
240	
241	.pause-controls {
242	  margin-top: 12px;
243	  padding: 10px 12px;
244	  background: var(--mc-tile-dirt), rgba(20, 14, 8, 0.9);
245	  outline: 2px solid rgba(0, 0, 0, 0.85);
246	  display: grid;
247	  gap: 3px;
248	}
249	
250	.pause-controls-row {
251	  display: flex;
252	  justify-content: space-between;
253	  gap: 16px;
254	  color: #d4d4d4;
255	  font-size: 11px;
256	  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.7);
257	}
258	
259	.pause-controls-row span:last-child {
260	  color: #f4f4f4;
261	  font-weight: 700;
262	}
263	
264	.debug-overlay {
265	  position: absolute;
266	  top: 10px;
267	  left: 10px;
268	  z-index: 5;
269	  display: grid;
270	  gap: 2px;
271	  justify-items: start;
272	  pointer-events: none;
273	  user-select: none;
274	}
275	
