277	  background: rgba(16, 16, 16, 0.45);
278	  color: #e8e8e8;
279	  font-family: var(--mc-font-mono);
280	  font-size: 12px;
281	  line-height: 1.35;
282	  padding: 1px 5px;
283	  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.7);
284	  white-space: pre;
285	}
