287	.click-hint {
288	  position: absolute;
289	  left: 50%;
290	  top: 38%;
291	  transform: translateX(-50%);
292	  z-index: 3;
293	  color: var(--mc-text-light);
294	  font-size: 15px;
295	  font-weight: 700;
296	  text-shadow: var(--mc-text-shadow);
297	  background: rgba(16, 16, 16, 0.45);
298	  padding: 6px 14px;
299	  outline: 2px solid rgba(0, 0, 0, 0.6);
300	  pointer-events: none;
301	  user-select: none;
302	  animation: click-hint-pulse 2.4s ease-in-out infinite;
303	}
304	
305	@keyframes click-hint-pulse {
306	  0%,
