type MinecraftGameProps = {
  world: WorldMeta;
  profile: Profile;
  onQuitToWorlds: () => void;
  /** Hardcore Game Over: erase the dead world and return to the world list. */
  onDeleteWorld: () => void;
  onReloadWorld: () => void;
};

export default function MinecraftGame({ world, profile, onQuitToWorlds, onDeleteWorld, onReloadWorld }: MinecraftGameProps) {
  const {
    attachMount,
    attachMinimap,
    locked,
    rendererError,
    gameMode,
    difficulty,
    hardcore,
    gameOver,
    giveCreativeItem,
    setGameMode,
    setDifficulty,
    selectedSlot,
    setSelectedSlot,
    capsActive,
    inventoryOpen,
    inventory,
    equippedArmor,
    armorPoints,
    hearts,
    hunger,
    oxygen,
    daylightPercent,
    passiveCount,
    hostileCount,
    respawnSeconds,
    paused,
    sleeping,
    craftingStation,
    container,
    boss,
    victory,
    activeEffects,
    xpLevel,
    xpProgress,
    debugOpen,
    debug,
    saveMessage,
    audioSettings,
    updateAudioSettings,
    skinId,
    updateSkin,
    hotbarSlots,
    recipes,
    maxHearts,
    maxHunger,
    maxOxygen,
    canCraft,
    craft,
    enchant,
    anvilCombine,
    anvilRepair,
    anvilRename,
    grindstoneStrip,
    swapInventorySlots,
    moveStack,
    toggleEquipArmor,
    unequipArmor,
    resumeNow,
    respawnNow,
    dismissVictory,
    saveNow,
    loadNow,
    resetNow,
    quitToWorlds
  } = useMinecraftGame({ world, profile, onQuitToWorlds, onReloadWorld });

  useEffect(() => {
    installUiTiles();
  }, []);

  if (rendererError) {
    return (
      <div className="game-root">
        <div className="renderer-error">
          <h2>Could not start the 3D renderer</h2>
          <p>WebGL appears to be unavailable in this browser ({rendererError}).</p>
          <p>Try enabling hardware acceleration or switching browsers, then reload.</p>
        </div>
      </div>
    );
  }

  const showClickHint = !locked && !paused && !inventoryOpen && respawnSeconds === 0;

  return (
    <div className="game-root">
      <div ref={attachMount} className="game-canvas-wrap" />
      <div className="vignette" aria-hidden="true" />

      {debugOpen ? <DebugOverlay debug={debug} passiveCount={passiveCount} hostileCount={hostileCount} daylightPercent={daylightPercent} /> : null}

      {showClickHint ? <div className="click-hint">Double-click to play</div> : null}

      <BossHealthBar boss={boss} />

      <ActiveEffects effects={activeEffects} />

      {saveMessage && !paused ? (
        <div className="hud-toast" role="status">
          {saveMessage}
        </div>
      ) : null}

      <div ref={attachMinimap} className="minimap" data-testid="minimap" />

      <div className="hud-bottom">
