.mc-button.danger {
  background: #8c3a34;
  border-color: #c98179 #4a1713 #4a1713 #c98179;
}

.pause-reset-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.pause-sound {
  display: grid;
  gap: 8px;
  margin-top: 4px;
}

.pause-sound-row {
  display: grid;
  grid-template-columns: 64px 1fr;
