}

.pause-skins-title {
  color: var(--mc-text-light);
  font-size: 13px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
}

.pause-skins-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
