  position: absolute;
  left: 50%;
  bottom: 96px;
  transform: translateX(-50%);
  z-index: 5;
  color: var(--mc-text-light);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  text-shadow: var(--mc-text-shadow);
